	open fun linkValidateRoutingStep(): Double {
		return (if (this.routing_step_authored > 0.0) FRef.f_SimulationOptions_routing_step_authored(this) else FRef.f_SimulationOptions_routing_step(this))!!.get()
	}

	open fun totalDurationMs(): Double {
		if (this.total_duration_ms >= 0.0) {
			return this.total_duration_ms
		}
		return cpp.SysMath.Floor_d((this.end_date - this.start_date) * 86400.0) * 1000.0
	}

